def average_Odd(n):
    """Write a python function to find the average of odd numbers till a given odd number."""
    total = 0
    count = 0
    for i in range(1, n + 1):
        if i % 2 == 1:
            total += i
            count += 1
    if count == 0:
        raise ValueError("n must be a positive integer with at least one odd number in range")
    return total / count
